package com.andye.warmod.antiair;import com.andye.warmod.icbm.IcbmFlightControllerManager;import com.andye.warmod.radar.*;import com.andye.warmod.warhead.*;import java.util.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.phys.Vec3;public final class StrategicMissileInterceptionService{private static final Map<ServerLevel,Set<UUID>> DONE=new WeakHashMap<>();private StrategicMissileInterceptionService(){}public static synchronized InterceptionResult intercept(ServerLevel l,UUID root,UUID interceptor,Vec3 pos){Set<UUID> done=DONE.computeIfAbsent(l,x->new HashSet<>());if(!done.add(root))return InterceptionResult.failed();WarheadPayloadType payload=null;var terminal=IncomingWarheadRegistry.get(l,root);if(terminal.isPresent()){payload=terminal.get().payloadType();if(!terminal.get().cancelForInterception(l,interceptor,pos)){done.remove(root);return InterceptionResult.failed();}IcbmFlightControllerManager.cancelForInterception(l,root,interceptor,pos);}else{var state=IcbmFlightControllerManager.targetState(l,root,l.getGameTime());if(state.isEmpty()){done.remove(root);return InterceptionResult.failed();}payload=state.get().payloadType();if(!IcbmFlightControllerManager.cancelForInterception(l,root,interceptor,pos)){done.remove(root);return InterceptionResult.failed();}}RadarTrackingService.removeTrack(l,root,RadarRemovalReason.INTERCEPTED);return InterceptionResult.success(payload);}}